basic_string& assign(InputIterator first, InputIterator last);

basic_string& assign(std::initializer_list<charT> ilist);

basic_string& insert(size_type pos, const basic_string& str);

code_example:
#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<char> vec = {'H', 'e', 'l', 'l', 'o'};
    std::string str;
    // Using assign with iterator range
    str.assign(vec.begin(), vec.end());
    std::cout << "Assigned from vector: " << str << std::endl;

    // Using assign with initializer_list
    str.assign({'W', 'o', 'r', 'l', 'd'});
    std::cout << "Assigned from initializer_list: " << str << std::endl;

    // Using insert to add a substring at position 5
    str.insert(5, " C++");
    std::cout << "After insert: " << str << std::endl;
    return 0;
}
